H=$1; until s=$(timeout 60 gh api "repos/mbadali25/useful-claude-add-ons/commits/$H/check-runs?per_page=100" --jq "[.check_runs[]|select(.status!=\"completed\")]|length" 2>/dev/null) && [ "$s" = 0 ] && [ "$(timeout 60 gh api "repos/mbadali25/useful-claude-add-ons/commits/$H/check-runs?per_page=100" --jq .total_count)" -gt 20 ]; do sleep 60; done; echo "done $H"; timeout 60 gh api "repos/mbadali25/useful-claude-add-ons/commits/$H/check-runs?per_page=100" --jq ".check_runs[] | select(.conclusion!=\"success\") | \"\(.conclusion) \(.name) \(.id)\""
